    assert len(caps['entries'])==54 and caps['excluded_ids']==[25,27,41,42,47,48] and demo['synthetic'] and not demo['empirical_skill_certified'];r=demo['research_report'];assert r['coverage']['planned']==3 and r['coverage']['matched']==2 and r['coverage']['missing_outcomes']==1 and r['model']['brier']['exact']=='17/50' and r['baseline']['brier']['exact']=='1/4' and r['comparison']['model_minus_baseline']=='9/100'
